edits.newText:
final cfg = settings.screenConfigNotifier.value;
final spectrum = settings.settingsNotifier.value;
final cassetteCfg = cfg is CassetteScreenConfig
    ? cfg as CassetteScreenConfig
    : null;

edits.oldText:
if (cfg is CassetteScreenConfig) ...[
  _Cycle(
    'void-settings-cassette-variant',
    'color scheme',
    cassetteVariantMeta[(cfg as CassetteScreenConfig).variant]!.label,
    () {
      final cur = cfg as CassetteScreenConfig;
      final next = CassetteVariant.values[
          (cur.variant.index + 1) % CassetteVariant.values.length];
      settings.saveScreenConfig(cur.copyWith(variant: next));
    },
  ),
],

